include <robotics.scad>
// TowerPro SG90 case envelope. Origin = case bottom centre. Long side along X, output on +X.
// OFFICIAL (TowerPro configure table)
B = 22.7;   // case length
D = 12.2;   // case width
C = 27.0;   // case height excl. spline (top of gear tower)
E = 32.3;   // length across mounting tabs
F = 17.0;   // case bottom to underside of tabs
// NOT PUBLISHED - plain conservative placeholders
tab_t   = 2.5;   // tab thickness
body_h  = 22.0;  // main body top (step under gear tower)
tower_l = 15.0;  // gear tower length, flush with +X end
r = 0.4;         // small edge break only, no effect on envelope

union() {
  // main body
  cuboid([B, D, body_h], rounding = r, edges = "Z", anchor = BOT);
  // raised gear tower on the +X end, full width
  translate([B/2 - tower_l/2, 0, 0])
    cuboid([tower_l, D, C], rounding = r, edges = "Z", anchor = BOT);
  // mounting tabs, full width, plain (hole pitch/diameter not published)
  translate([0, 0, F]) cuboid([E, D, tab_t], anchor = BOT);
}

include <robotics.scad>
// Output spline as a plain cylinder. Origin = axis on top face of gear tower (z = C).
A = 30.3; C = 27.0;     // official
d = 4.8;                // NOT published, placeholder
cyl(d = d, h = A - C, chamfer2 = 0.3, anchor = BOT, $fn = 48);
